"""Saved-only original controlled-access crossing and notice measurements."""
import argparse
import hashlib
import json
from pathlib import Path
from package_spec import CAMERA_NAMES
from access_probe import measure

def need(ok,message):
    if not ok:raise ValueError(message)
def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def source(root,name):
    path=root/name
    if not path.is_file() or path.is_symlink():raise ValueError('Missing required source: '+name)
    return path

def source_sealed_access_measurement(value):
    return value

def analyze(attempt):
    root=Path(attempt).resolve()
    config=json.loads(source(root,'config.json').read_text())
    case=config['selected_case_id']
    receipt=json.loads(source(root,'original-source-receipt.json').read_text())
    diagnostic=receipt.get('diagnostic_fixture') is True
    need(receipt.get('source_kind')==('synthetic_diagnostic_fixture' if diagnostic else 'original_native_capture') and receipt.get('case_id')==case,'exact original/diagnostic source receipt differs')
    names={'history_sha256':'access-history.json','trace_sha256':'trace.jsonl','frame_map_sha256':'video_frames.jsonl','measurement_sha256':'access-measurement.json'}
    for key,name in names.items():need(receipt.get(key)==sha(source(root,name)),'sealed access source differs: '+key)
    history=json.loads(source(root,'access-history.json').read_text())
    rows=history['samples']
    trace=[json.loads(line) for line in source(root,'trace.jsonl').read_text().splitlines()]
    frame_map=[json.loads(line) for line in source(root,'video_frames.jsonl').read_text().splitlines()]
    need(history.get('assignment_id')==config['assignment_id'] and history.get('case_id')==case and len(rows)==len(trace)==len(frame_map) and len(rows)>=3,'access source row count or identity differs')
    for index,(row,mapped,motion) in enumerate(zip(rows,frame_map,trace)):
        need(row['frame']==mapped['video_frame']==index and mapped['native_frame']==mapped['carla_frame']==motion['frame']==row['original_frame'] and row['time_s']==mapped['time_s']==motion['time_s'] and abs(motion['speed_mps']-row['speed_mps'])<1e-6 and row['driver_id']==history['driver_actor_id'],'original vehicle/trace/video frame join differs')
        if not diagnostic:need(row.get('boundary_xy')==row['position_xyz_m'][:2],'original boundary coordinate differs from Native pose')
    site={key:history[key] for key in ('authority_source','highway_source','boundary_source','controlled_access_determination','boundary_x_m','indicated_points','official_notice_source')}
    site['vehicle_id']=history['driver_actor_id']
    frames=[{'original_frame':row['original_frame'],'time_s':row['time_s'],'vehicle_id':row['driver_id'],'xy':row['boundary_xy'],'source_ref':row['source_ref']} for row in rows]
    measured=measure(site,frames)
    need(json.loads(source(root,'access-measurement.json').read_text())==measured,'original access measurement differs from source frames')
    values={
      'controlled_access_authority':{'determination':history['controlled_access_determination'],'authority_source':history['authority_source']},
      'public_highway_boundary':{'public_highway':history['public_highway'],'boundary_x_m':history['boundary_x_m'],'highway_source':history['highway_source'],'boundary_source':history['boundary_source']},
      'official_erected_devices':{'authority_designated':history['authority_designated_devices'],'official_notice_source':history['official_notice_source'],'devices':[{'device_id':p['device_id'],'source':p['device_source'],'erected':p['erected']} for p in history['indicated_points']]},
      'designated_access_points':{'points':history['indicated_points']},
      'notice_visibility':{'point':history['target_point'],'source_notice_visible':history['target_point']['notice_visible'],'pixel_review_pending':True},
      'vehicle_boundary_crossing':{'crossings':measured['crossings'],'all_at_visible_indicated_points':measured['all_crossings_at_indicated_points']},
      'vehicle_motion':{'first_position_m':trace[0]['position_m'],'last_position_m':trace[-1]['position_m'],'maximum_speed_mps':max(row['speed_mps'] for row in rows)}}
    contract_sources={name:sha(source(root,name)) for name in ('access-history.json','original-source-receipt.json','trace.jsonl')}
    measurements={name:{'method':'source_sealed_access_measurement','value':source_sealed_access_measurement(value),'sources':contract_sources} for name,value in values.items()}
    evidence=[]
    for channel in config['case']['recording_description']['channels']:
        name=channel['name'];output=root/('channel-'+name+'.jsonl')
        content=''.join(json.dumps({'time_s':row['time_s'],'value':row['boundary_xy'] if name=='vehicle_boundary_crossing' else row['position_xyz_m'] if name=='vehicle_motion' else values[name]},sort_keys=True)+'\n' for row in rows)
        if output.exists():need(output.read_text()==content,'derived channel differs from saved source')
        else:output.write_text(content)
        evidence.append({'name':name,'unit':channel['unit'],'reference':output.name})
    context=root/'channel-reviewed_controlled_access_site.json'
    content=json.dumps({'reviewed_controlled_access_site':{'reviewed_site_sha256':history['reviewed_site_sha256'],'authority_source':history['authority_source'],'official_notice_source':history['official_notice_source']}},sort_keys=True)+'\n'
    if context.exists():need(context.read_text()==content,'reviewed site context differs')
    else:context.write_text(content)
    evidence.append({'name':'reviewed_controlled_access_site','unit':'source record','reference':context.name})
    target={'target':'source-reviewed controlled-access boundary crossing','requested':history['requested_direction'],'measured':measured['crossings'],'method':'original Native pose plus separate authority and device source','tolerance':0,'matched':bool(measured['crossings']),'physical_cause_confirmed':False,'cause_evidence':contract_sources}
    from worker_exchange.native_output import physical_result,write_result
    result={'case_id':case,'measured_values':values,'target_checks':[target],'setup_confirmed':False,'behavior_attempted':False,'maneuver_completed':False,'termination_reason':'saved physical and source review pending','physical_failure_flags':['physical_acceptance_unverified'],'trace_reference':'trace.jsonl','video_references':[x+'.mkv' for x in CAMERA_NAMES],'video_frame_map_reference':'video_frames.jsonl','recording_description':config['case']['recording_description'],'recording_evidence':evidence,'realized_observables':{},'diagnostic_fixture':diagnostic,'physical_acceptance_claimed':False,'legal_verdict_claimed':False}
    result=physical_result(root,result);write_result(root,result)
    return {'format':'worker-analysis-report','case_id':case,'analysis_complete':True,'diagnostic_fixture':diagnostic,'physical_acceptance_claimed':False,'legal_verdict_claimed':False,'measurements':measurements,'physical_checks':result['physical_checks'],'realized_observables':result['realized_observables'],'limitations':['Map road type cannot establish controlled-access status; independent authority and official device notice review required.']}
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    if args.output.exists():raise ValueError('retain prior analysis report')
    args.output.write_text(json.dumps(analyze(args.attempt),indent=2)+'\n')

"""Source-bound crossing observations for NRS 484B.587(1).

Access designation and official notice come from authority/device sources; a
map road type alone is insufficient to establish controlled-access status.
"""

from math import isfinite


def validate_site(site):
    required = {"authority_source", "highway_source", "boundary_source",
                "controlled_access_determination", "boundary_x_m", "indicated_points",
                "official_notice_source", "vehicle_id"}
    if required - site.keys() or not all(site[k] for k in
                                          ("authority_source", "highway_source",
                                           "boundary_source", "official_notice_source",
                                           "vehicle_id")):
        raise ValueError("missing authority, highway boundary or device source")
    if not site["controlled_access_determination"]:
        raise ValueError("controlled-access status not established")
    if not isfinite(site["boundary_x_m"]) or not site["indicated_points"]:
        raise ValueError("missing access boundary or indicated points")
    for point in site["indicated_points"]:
        if set(("point_id", "direction", "y_min_m", "y_max_m", "device_id",
                "device_source", "erected", "notice_visible")) - point.keys():
            raise ValueError("incomplete indicated access point")
        if not point["device_source"] or not point["device_id"] or not point["erected"]:
            raise ValueError("official device not established")
        if point["direction"] not in ("entry", "exit") or point["y_min_m"] > point["y_max_m"]:
            raise ValueError("invalid access point geometry")


def measure(site, frames):
    validate_site(site)
    required = {"original_frame", "time_s", "vehicle_id", "xy", "source_ref"}
    if len(frames) < 2 or any(required - f.keys() or not f["source_ref"] for f in frames):
        raise ValueError("missing original vehicle route")
    if any(f["vehicle_id"] != site["vehicle_id"] for f in frames):
        raise ValueError("vehicle identity mismatch")
    if any(frames[i]["original_frame"] >= frames[i + 1]["original_frame"] or
           frames[i]["time_s"] >= frames[i + 1]["time_s"]
           for i in range(len(frames) - 1)):
        raise ValueError("nonmonotone original route")
    if any(len(f["xy"]) != 2 or not all(isfinite(v) for v in f["xy"]) for f in frames):
        raise ValueError("invalid route position")
    boundary = site["boundary_x_m"]
    crossings = []
    for prior, current in zip(frames, frames[1:]):
        x0, y0 = prior["xy"]
        x1, y1 = current["xy"]
        if (x0 < boundary <= x1) or (x1 < boundary <= x0):
            direction = "entry" if x1 > x0 else "exit"
            y_cross = y0 + (y1 - y0) * (boundary - x0) / (x1 - x0)
            matching = [p for p in site["indicated_points"]
                        if p["direction"] == direction and p["notice_visible"] and
                        p["y_min_m"] <= y_cross <= p["y_max_m"]]
            crossings.append({"original_frame": current["original_frame"],
                              "direction": direction, "crossing_y_m": y_cross,
                              "indicated_point_ids": [p["point_id"] for p in matching]})
    if not crossings:
        raise ValueError("highway boundary crossing not observed")
    return {"crossings": crossings,
            "all_crossings_at_indicated_points": all(c["indicated_point_ids"] for c in crossings),
            "source_refs": sorted(set([site[k] for k in
                                       ("authority_source", "highway_source",
                                        "boundary_source", "official_notice_source")] +
                                      [f["source_ref"] for f in frames] +
                                      [p["device_source"] for p in site["indicated_points"]]))}

"""Source-gated Native access-route construction; map road type is insufficient."""
import math
from package_spec import AID
from access_probe import validate_site

CASES = {'indicated_entry': ('entry', True, True), 'unindicated_entry': ('entry', False, True), 'notice_not_visible': ('entry', True, False), 'indicated_exit': ('exit', True, True), 'unindicated_exit': ('exit', False, True)}

def number(value):
    if isinstance(value, bool) or not isinstance(value, (int,float)) or not math.isfinite(value):
        raise ValueError('finite numeric source value required')
    return float(value)

def construct(site, case):
    if site.get('assignment_id') != AID or site.get('case_id') != case or site.get('source_kind') != 'original_native_access_survey' or site.get('reviewed_original_native_site') is not True:
        raise ValueError('exact reviewed original Native access site required')
    suffix = case.removeprefix(AID + '__')
    if suffix not in CASES:
        raise ValueError('unknown exact access case')
    direction, indicated, visible = CASES[suffix]
    for key in ('source_id','map_name','map_sha256','authority_source','highway_source','boundary_source','official_notice_source','driver_actor_id'):
        if not site.get(key):
            raise ValueError('separate source fact absent: '+key)
    if site.get('public_highway') is not True or site.get('controlled_access_determination') is not True or site.get('authority_designated_devices') is not True:
        raise ValueError('public authority controlled-access and official device designation required')
    if site.get('map_road_type_as_legal_source') is True:
        raise ValueError('map road type cannot establish legal controlled-access status')
    if site.get('requested_direction') != direction or site.get('requested_indicated') is not indicated or site.get('requested_notice_visible') is not visible:
        raise ValueError('case-specific access request differs')
    probe = {'authority_source':site['authority_source'],'highway_source':site['highway_source'],'boundary_source':site['boundary_source'],'controlled_access_determination':True,'boundary_x_m':site.get('boundary_x_m'),'indicated_points':site.get('indicated_points'),'official_notice_source':site['official_notice_source'],'vehicle_id':site['driver_actor_id']}
    validate_site(probe)
    point = site.get('target_point')
    if not isinstance(point,dict) or point.get('direction') != direction or point.get('indicated') is not indicated or point.get('notice_visible') is not visible or not point.get('source_ref'):
        raise ValueError('source-backed exact target crossing point required')
    y = number(point.get('crossing_y_m'))
    matches = [p for p in probe['indicated_points'] if p['direction']==direction and p['y_min_m']<=y<=p['y_max_m']]
    if indicated and (len(matches)!=1 or matches[0]['notice_visible'] is not visible or matches[0]['point_id']!=point.get('point_id')):
        raise ValueError('official indicated access point or visibility differs')
    if not indicated and matches:
        raise ValueError('unindicated crossing overlaps designated point')
    spawn=site.get('native_spawn')
    if not isinstance(spawn,dict) or not spawn.get('source_id') or not spawn.get('blueprint_id') or not isinstance(spawn.get('pose_xyz_ypr'),list) or len(spawn['pose_xyz_ypr'])!=6:
        raise ValueError('source-backed Native vehicle pose required')
    for value in spawn['pose_xyz_ypr']:number(value)
    route=site.get('trajectory')
    if not isinstance(route,dict) or not route.get('source_id') or not isinstance(route.get('points_xy'),list) or len(route['points_xy'])<3:
        raise ValueError('source-backed drivable route required')
    points=route['points_xy']
    for xy in points:
        if not isinstance(xy,list) or len(xy)!=2:raise ValueError('route xy source required')
        for value in xy:number(value)
    b=probe['boundary_x_m']
    if (points[0][0]<b<points[-1][0]) != (direction=='entry') or (points[0][0]>b>points[-1][0]) != (direction=='exit'):
        raise ValueError('source route does not cross boundary in exact direction')
    return {'case_id':case,'direction':direction,'indicated':indicated,'notice_visible':visible,'crossing_y_m':y,'trajectory_xy':points,'probe_site':probe,'native_readback_required':True}
